package main
import("crypto/sha256";"encoding/binary";"encoding/hex";"encoding/json";"flag";"fmt";"os";"os/exec";"bytes";"runtime";"sort";"time")
const schema="acc60-u16-v1"
func mix(x uint64)uint64{x+=0x9e3779b97f4a7c15;x=(x^(x>>30))*0xbf58476d1ce4e5b9;x=(x^(x>>27))*0x94d049bb133111eb;return x^(x>>31)}
func weight(seed uint64,r,c int)int64{return int64(mix(seed^uint64(r)*0x94d049bb133111eb^uint64(c)*0xbf58476d1ce4e5b9)%16)-8}
func input(seed uint64,t,c int)int64{return int64(mix(seed^uint64(t)*0x71cf0bd3^uint64(c)*0xa0761d6478bd642f)%16)-8}
func put(h interface{Write([]byte)(int,error)},v uint64){var b[8]byte;binary.LittleEndian.PutUint64(b[:],v);h.Write(b[:])}
type receipt struct{Schema,Mode,OS,WeightsSHA,InputSHA,OutputSHA string;Seed uint64;N,Repetitions,Inputs,Outputs,Correct int;BinaryBytes int64;PeakRSSBytes uint64}
func compute(seed uint64,n int,mode string)(receipt,error){var out receipt;if n!=16&&n!=64&&n!=128&&n!=256{return out,fmt.Errorf("size")};if mode!="ARRAY"&&mode!="TILED"&&mode!="COMPILED"{return out,fmt.Errorf("mode")}
 wh,ih,oh:=sha256.New(),sha256.New(),sha256.New();w:=make([]int8,n*n);for r:=0;r<n;r++{for c:=0;c<n;c++{v:=weight(seed,r,c);w[r*n+c]=int8(v);put(wh,uint64(v))}}
 correct:=0
 for rep:=0;rep<3;rep++{for t:=0;t<4096;t++{x:=make([]int64,n);for j:=range x{x[j]=input(seed,t,j);put(ih,uint64(x[j]))};for r:=0;r<n;r++{sum:=int64(0);if mode=="TILED"{for block:=0;block<n;block+=8{for c:=block;c<block+8;c++{sum+=int64(w[r*n+c])*x[c]}}}else if mode=="COMPILED"{for c:=0;c<n;c++{sum+=compiledWeight(seed,r,c)*x[c]}}else{for c:=0;c<n;c++{sum+=int64(w[r*n+c])*x[c]}}
 reference:=int64(0);for c:=0;c<n;c++{reference+=weight(seed,r,c)*x[c]};if sum==reference{correct++};put(oh,uint64(sum))}}}
 exe,e:=os.Executable();if e!=nil{return out,e};st,e:=os.Stat(exe);if e!=nil{return out,e};rss,e:=peakResidentBytes();if e!=nil{return out,e}
 return receipt{Schema:schema,Mode:mode,OS:runtime.GOOS,WeightsSHA:hex.EncodeToString(wh.Sum(nil)),InputSHA:hex.EncodeToString(ih.Sum(nil)),OutputSHA:hex.EncodeToString(oh.Sum(nil)),Seed:seed,N:n,Repetitions:3,Inputs:4096*3,Outputs:4096*n*3,Correct:correct,BinaryBytes:st.Size(),PeakRSSBytes:rss},nil}
type trial struct{Receipt receipt;CPUSeconds,WallSeconds float64}
type cohort struct{N int;CPU,RSS,Binary map[string]float64;CPURatio,RSSRatio,BinaryRatio float64;Pass bool}
type report struct{Schema,OS,Classification string;Workers int;Trials []trial;Cohorts []cohort}
func med(a []float64)float64{sort.Float64s(a);return a[len(a)/2]}
func child(exe,mode string,n int,seed uint64)(trial,error){var t trial;c:=exec.Command(exe,"-child","-mode",mode,"-n",fmt.Sprint(n),"-seed",fmt.Sprint(seed));var o,e bytes.Buffer;c.Stdout=&o;c.Stderr=&e;start:=time.Now();err:=c.Run();wall:=time.Since(start).Seconds();if err!=nil{return t,fmt.Errorf("%s %d: %w %s",mode,n,err,e.String())};cpu:=(c.ProcessState.UserTime()+c.ProcessState.SystemTime()).Seconds();if cpu<=0{return t,fmt.Errorf("zero child CPU")};var w receipt;if err=json.Unmarshal(o.Bytes(),&w);err!=nil{return t,err};if w.Schema!=schema||w.N!=n||w.Mode!=mode||w.Seed!=seed||w.PeakRSSBytes==0||w.Correct!=w.Outputs{return t,fmt.Errorf("invalid receipt")};return trial{w,cpu,wall},nil}
func drive(path string)error{exe,e:=os.Executable();if e!=nil{return e};r:=report{Schema:schema,OS:runtime.GOOS};for _,n:=range []int{16,64,128,256}{for i,seed:=range []uint64{116101,116103,116107,116109,116111}{arms:=[]string{"ARRAY","TILED","COMPILED"};if i%2==1{arms=[]string{"COMPILED","TILED","ARRAY"}};for _,arm:=range arms{t,e:=child(exe,arm,n,seed);if e!=nil{return e};r.Trials=append(r.Trials,t)}};c:=cohort{N:n,CPU:map[string]float64{},RSS:map[string]float64{},Binary:map[string]float64{}};paired:=map[uint64]string{};for _,arm:=range []string{"ARRAY","TILED","COMPILED"}{var cpu,rss,bin []float64;for _,t:=range r.Trials{w:=t.Receipt;if w.N!=n||w.Mode!=arm{continue};h:=w.WeightsSHA+"/"+w.InputSHA+"/"+w.OutputSHA;if old,ok:=paired[w.Seed];ok&&old!=h{return fmt.Errorf("prediction or source mismatch")};paired[w.Seed]=h;cpu=append(cpu,t.CPUSeconds);rss=append(rss,float64(w.PeakRSSBytes));bin=append(bin,float64(w.BinaryBytes))};if len(cpu)!=5{return fmt.Errorf("missing trials")};c.CPU[arm],c.RSS[arm],c.Binary[arm]=med(cpu),med(rss),med(bin)}
 fastest:="ARRAY";if c.CPU["TILED"]<c.CPU[fastest]{fastest="TILED"};c.CPURatio=c.CPU["COMPILED"]/c.CPU[fastest];c.RSSRatio=c.RSS["COMPILED"]/c.RSS[fastest];c.BinaryRatio=c.Binary["COMPILED"]/c.Binary["ARRAY"];c.Pass=c.CPURatio<=.85&&c.RSSRatio<=1.10&&c.BinaryRatio<=1.25;r.Cohorts=append(r.Cohorts,c)}
 r.Workers=len(r.Trials);if r.Workers!=60{return fmt.Errorf("missing children")};r.Classification="U16_NO_GENERAL_VERIFIED_NATIVE_GO_RESOURCE_WIN";pass:=true;for _,c:=range r.Cohorts{pass=pass&&c.Pass};if pass{r.Classification="U16_RESTRICTED_SYNTHETIC_GO_CODEGEN_POSITIVE_ONLY"};b,e:=json.MarshalIndent(r,"","  ");if e!=nil{return e};if e=os.WriteFile(path,b,0644);e!=nil{return e};fmt.Println("ACC60_U16_60_WORKERS_PASS");fmt.Println("ACC60_U16_CLASSIFICATION="+r.Classification);return nil}
func main(){isChild:=flag.Bool("child",false,"");seed:=flag.Uint64("seed",116101,"");n:=flag.Int("n",16,"");mode:=flag.String("mode","ARRAY","");out:=flag.String("out","acc60-report.json","");flag.Parse();var e error;if *isChild{var r receipt;r,e=compute(*seed,*n,*mode);if e==nil{e=json.NewEncoder(os.Stdout).Encode(r)}}else{e=drive(*out)};if e!=nil{fmt.Fprintln(os.Stderr,"ACC60_U16_BLOCKED:",e);os.Exit(1)}}
